package com.company.platform.aigateway.api;
import com.company.platform.aigateway.application.AIException;import java.time.Instant;import java.util.Map;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import org.springframework.web.bind.MethodArgumentNotValidException;
@RestControllerAdvice public class AIExceptionHandler { @ExceptionHandler(AIException.class) ResponseEntity<?> ai(AIException e){return ResponseEntity.status(e.status()).body(Map.of("code",e.code(),"message",e.getMessage(),"timestamp",Instant.now()));} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<?> invalid(){return ResponseEntity.badRequest().body(Map.of("code","AI_INVALID_REQUEST","message","request is invalid","timestamp",Instant.now()));} @ExceptionHandler(Exception.class) ResponseEntity<?> generic(){return ResponseEntity.internalServerError().body(Map.of("code","AI_INTERNAL_ERROR","message","AI request failed","timestamp",Instant.now()));} }
